// The pages: an overview of what the domain holds, a list per aggregate (table.ts), one instance
// (detail.ts), and a form per command generated from the command's attributes. Every page is built
// into the frame in shell.ts. Lifecycle state is a badge, and a lifecycle move is offered only from
// the states it applies in.
import type { Aggregate, Attr, Command, Query } from "../schema.ts";
import { SCHEMA } from "../schema.ts";
import { confirmDialog, detailPage as detail } from "./detail.ts";
import type { Submitted } from "./detail.ts";
import { fields } from "./fields.ts";
import type { Invalid } from "./fields.ts";
import { esc, href, refusal } from "./html.ts";
import { countMark, page } from "./shell.ts";
import type { Crumb } from "./shell.ts";
import { listPage as list } from "./table.ts";
import { commandLabel, label, plural } from "./words.ts";

type State = Record<string, unknown>;
type Row = [string, State];

export type { Submitted };

const OVERVIEW: Crumb = ["Overview", href()];

const head = (title: string, note: string): string =>
  `<div class="mb-6"><h1 class="text-3xl">${esc(title)}</h1><p class="mt-1 max-w-prose text-muted">${esc(note)}</p></div>`;

/** The overview: every aggregate the domain declares, with what it is and how much of it there is. */
export function home(): string {
  const items = SCHEMA.aggregates.map((agg) => {
    const note = agg.description ? `<span class="text-muted">${esc(agg.description)}</span>` : "";
    return `<li class="flex items-center justify-between gap-4"><a class="grid flex-1 gap-0.5 p-4 hover:bg-base-200/60" href="${esc(href(agg.name))}"><span class="text-base font-semibold">${esc(plural(agg.name))}</span>${note}</a><span class="pr-4 tabular-nums text-muted">${countMark(agg.name)}</span></li>`;
  });
  const body = `${head(SCHEMA.domain, "Choose what to edit.")}
<ul class="divide-y divide-base-300 border-y border-base-300 bg-base-100">
${items.join("\n")}
</ul>`;
  return page("Overview", body, { crumbs: [["Overview"]] });
}

/** The page for a path that names nothing. */
export function notFound(what: string): string {
  const body = `${head("Not found", what)}
<p><a class="btn" href="${esc(href())}">Back to the overview</a></p>`;
  return page("Not found", body, { crumbs: [OVERVIEW, ["Not found"]] });
}

/** An aggregate's list. */
export function listPage(agg: Aggregate, rows: Row[], query: Query | null, error: string | null, asked = true): string {
  return page(plural(agg.name), list(agg, rows, query, error, asked), { active: agg.name, crumbs: [OVERVIEW, [plural(agg.name)]] });
}

/** One instance. */
export function detailPage(agg: Aggregate, id: string, values: State, shown: Submitted | null): string {
  const crumbs: Crumb[] = [OVERVIEW, [plural(agg.name), href(agg.name)], [id]];
  return page(id, detail(agg, id, values, shown), { active: agg.name, crumbs });
}

/**
 * What a command's form starts from: the instance's values, and for a rich-text body the instance
 * has not set yet (a draft not yet saved), the body it holds of the same shape, so an edit begins
 * from the current text and not an empty page.
 */
function startingValues(agg: Aggregate, command: Command, state: State): State {
  const values = { ...state };
  for (const attr of command.attributes.filter((candidate: Attr) => candidate.widget === "body" && values[candidate.name] == null)) {
    const held = agg.attributes.find((other) => other.type === attr.type && other.name !== attr.name && state[other.name] != null);
    if (held) values[attr.name] = state[held.name];
  }
  return values;
}

const FORM = "command-form";

function invalidOf(own: Submitted | null): Invalid | null {
  return own?.field && own.message ? { field: own.field, message: own.message.replace(/^.*?: /s, "") } : null;
}

/** A form for one command; `to` adds the id input a command acting on another aggregate needs. */
export function commandForm(agg: Aggregate, command: Command, action: string, shown: Submitted | null, state: State = {}, to = false, cancel = href(agg.name)): string {
  const own = shown && shown.command === command.name ? shown : null;
  const note = command.goal ? `<p class="mb-4 max-w-prose text-muted">${esc(command.goal)}.</p>` : "";
  const target = to
    ? `<div class="my-4 grid gap-1"><label for="f-to" class="font-semibold">${esc(command.on ?? "")} id <span class="text-primary" aria-hidden="true">*</span></label><input type="text" class="input w-full max-w-xl" id="f-to" name="__to" value="${esc(own?.values.__to ?? "")}"></div>`
    : "";
  const confirm = command.destructive ? ` data-confirm="confirm-${esc(command.name)}"` : "";
  const text = esc(commandLabel(agg, command));
  const submit = command.destructive
    ? `<button type="submit" class="btn btn-error" data-busy${confirm}>${text}</button>`
    : `<button type="submit" class="btn btn-neutral" data-busy>${text}</button>`;
  const dialog = command.destructive ? confirmDialog(agg, command, action, "", FORM) : "";
  return `<form class="max-w-3xl" id="${FORM}" method="post" action="${esc(action)}" data-form>
${refusal(own?.message ?? null)}${note}
${target}
${fields(agg, command.attributes, own ? own.values : startingValues(agg, command, state), invalidOf(own))}
<div class="sticky bottom-0 z-10 -mx-4 mt-8 flex items-center justify-end gap-2 border-t border-base-300 bg-base-100 px-4 py-3 shadow-[0_-8px_16px_-12px_rgb(0_0_0/0.25)]"><p class="mr-auto text-xs text-muted"><span class="text-primary" aria-hidden="true">*</span> Required</p><a class="btn btn-ghost" href="${esc(cancel)}">Cancel</a>${submit}</div>
</form>
${dialog}`;
}

/** The page of one creating command (or a command that acts on another aggregate's instance). */
export function commandPage(agg: Aggregate, command: Command, action: string, shown: Submitted | null): string {
  const crumbs: Crumb[] = [OVERVIEW, [plural(agg.name), href(agg.name)], [commandLabel(agg, command)]];
  const form = commandForm(agg, command, action, shown, {}, command.on !== null && command.on !== agg.name);
  return page(commandLabel(agg, command), `${head(commandLabel(agg, command), label(agg.name))}\n${form}`, { active: agg.name, crumbs });
}

/** The page of a command that acts on one instance: its form, or the question a destructive one asks. */
export function instanceCommandPage(agg: Aggregate, id: string, command: Command, values: State, shown: Submitted | null): string {
  const action = href(agg.name, "id", id, command.name);
  const crumbs: Crumb[] = [OVERVIEW, [plural(agg.name), href(agg.name)], [id, href(agg.name, "id", id)], [commandLabel(agg, command)]];
  const title = head(commandLabel(agg, command), `${label(agg.name)} ${id}`);
  const cancel = href(agg.name, "id", id);
  if (command.destructive && command.attributes.length === 0) {
    const own = shown && shown.command === command.name ? shown.message : null;
    const ask = `<form class="max-w-3xl" method="post" action="${esc(action)}" data-form>${refusal(own)}<p>${esc(command.goal ?? `This applies to ${id}`)}. Choose ${esc(commandLabel(agg, command))} to go ahead.</p>
<div class="mt-6 flex justify-end gap-2"><a class="btn btn-ghost" href="${esc(cancel)}">Cancel</a><button type="submit" class="btn btn-error" data-busy>${esc(commandLabel(agg, command))}</button></div></form>`;
    return page(commandLabel(agg, command), `${title}\n${ask}`, { active: agg.name, crumbs });
  }
  return page(commandLabel(agg, command), `${title}\n${commandForm(agg, command, action, shown, values, false, cancel)}`, { active: agg.name, crumbs });
}
